import{_ as i,o as a,c as e,am as t}from"./chunks/framework.CiF4W93w.js";const h=JSON.parse('{"title":"面试总结20203","description":"","frontmatter":{"title":"面试总结20203","excerpt":"面试总结20203","date":"2024-03-18 14:06:52","updated":"2024-03-18 14:06:52"},"headers":[],"relativePath":"Java面试准备/Java 面试准备 2024版本- 简历/面试总结20203/index.md","filePath":"Java面试准备/Java 面试准备 2024版本- 简历/面试总结20203/index.md","lastUpdated":null}'),u={name:"Java面试准备/Java 面试准备 2024版本- 简历/面试总结20203/index.md"};function r(o,l,n,s,d,p){return a(),e("div",null,[...l[0]||(l[0]=[t('<h4 id="面试记录" tabindex="-1">面试记录 <a class="header-anchor" href="#面试记录" aria-label="Permalink to &quot;面试记录&quot;">​</a></h4><ul><li>20240318 图元科技（挂） 笔试后面试 自研 薪资：13K</li><li>20240325 航鸿达科技（挂) 自研 薪资：13K（因为多说了一句是干派遣的，直接说面试就到这吧）</li><li>20240329 酷宅科技（二面挂） 自研 薪资：13K</li><li>20240402 同行者科技（笔试挂） 自研 薪资：13K</li><li>20240407 优篮子科技有限公司（挂） 自研 薪资：15K</li><li>20240409 日浩集团（挂） 自研 薪资：13K（面试没太大问题，对方只能给 12）</li><li>20240409 神州信息（外包，过） 薪资：14K - 16K 没拿这个Offer</li><li>20240412 丽迅科技(挂) 自研 期待薪资：14K（面试感觉没太大问题，对方给的区间是13-15）</li><li>20240516 汇信昌（暂无后续，挂） 自研 薪资：15K</li><li>20240520 彩生活（初面表现一般，领导面表现不好，挂） 自研 薪资：15K</li><li>20240521 达博威科技(中国平安) 外包 过 给的钱太低了</li><li>20240522 深圳易立德（华为驻场） 外包 一面过 二面技术面过，综合评价：考虑到稳定性，对方没有给 Offer</li><li>20240523 博彦科技（Shine 外包） 过</li><li>20240530 太平洋网络 自研 二面挂 13K 15薪</li></ul><h4 id="面试题" tabindex="-1">面试题 <a class="header-anchor" href="#面试题" aria-label="Permalink to &quot;面试题&quot;">​</a></h4><ul><li>八股 <ul><li>系统设计 <ul><li><strong>项目授权你们项目是怎么做的</strong> 🚩</li><li>登录认证你们系统怎么做的</li></ul></li><li>SpringCloud <ul><li>你熟悉SpringCloud 的哪些组件</li><li>Gateway 你们一般怎么使用</li><li>SpringCloud 和 SpringBoot 有什么区别</li></ul></li><li>Redis <ul><li>Redis 缓存更新是怎么做的</li><li>你们项目中 Redis 是做什么的</li><li>Redis 的集群模式了解吗，它们之间的复制是怎么操作的</li><li>Redis 的内存讨论</li><li>Reids 的键值淘汰策略</li><li>将数据库用户表的信息存入到缓存中，建议使用什么数据结构</li></ul></li><li>Spring <ul><li>讲一下 AOP，以及具体如何使用的</li><li>说一下 spring 的传播事务</li></ul></li><li>基础 <ul><li>双层循环中的作用 continue、break、return 的区别</li><li>讲一下 valatile 关键字在你们项目中的使用</li><li>线程的状态有几种知道吗，当一个线程进行阻塞，如何进行唤醒，或者问一个问题，如何让两个线程交替执行。</li><li>说一下 HashMap 的底层实现</li><li>说一下死锁你们怎么处理的</li><li>aomic 类的使用</li><li>ThreadLocal 类你们项目中怎么用的。</li><li>HashMap 的 put 方法流程是怎么样的</li><li>线程池的核心参数有哪些</li></ul></li><li>JVM <ul><li>你们项目中垃圾回收器是使用的什么垃圾回收器，以及使用的什么回收算法</li></ul></li><li>MySQL <ul><li>说一下 mysql 的慢查询分析，以及索引优化注意的地方</li><li>什么时候会索引失效</li><li>说一下 mysql 的隔离级别</li><li>说一下 mysql 中的关键字优先级</li><li>正常我们使用 ORM 框架，从 ORM 框架 到 SQL 执行的这个过程你了解多少。</li><li>同一个事务中，如果先执行更新，后面的查询会查询到更新后最新的数据吗。</li></ul></li><li>SpringMVC <ul><li>SpringMVC 的请求流程是怎么样的</li></ul></li><li>MQ <ul><li>如何保证消息不丢失</li><li>如何避免消息重复消费</li><li>如果在客服端发生了报错：发生消息超时，你会从哪些方面去排查和定位。</li></ul></li><li>设计模式 <ul><li>设计模式了解多少，Spring 中使用到了哪些设计模式吗</li></ul></li><li>Docker <ul><li>Docket 的网络模式有哪几种</li><li>讲一下 Docket compose 如何使用的</li><li>讲一下容器服务编排调度</li><li>讲一下 docker 的常用命令</li></ul></li><li>Nginx <ul><li>文件从服务器A 的一个文件夹 到 服务器 B 使用什么命令可以搞</li></ul></li><li>NIO <ul><li>NIO 你了解吗</li></ul></li></ul></li><li>项目 <ul><li>简单介绍一下你最近做的这个项目，以及你主要负责的版块</li></ul></li><li>场景 <ul><li>讲一下你们项目中 socket 监听 的使用，以及你对于 socket 和 websocket 的使用具体使用案例和理解。</li><li>两个线程交互打印如何做</li><li>装饰器设计模式和组合模式的区别你讲一下，怎么用的</li><li>比如说我有一堆无序的元素，我想要让他放入到一个先进先出的集合中，你会怎么做</li><li>如果有这么一个场景，需要遍历 D 盘下所有目录和文件，需要快速获取到我想要的文件（根据文件名模糊查询），需要怎么做</li><li>接口幂等是如何保证的</li><li>后端给前端推送消息有哪几种方式</li></ul></li><li>前端 <ul><li>Vue 写过组件吗，怎么进行传值的</li><li>讲一下 Vue 的 组件生命周期</li></ul></li><li>不重要 <ul><li>你们系统安全测评怎么做的</li><li>修复过哪些系统漏洞</li></ul></li></ul><p><a href="/java/Java面试准备/Java 面试准备 2024版本- 简历/面试总结20203/面试总结20203回答版.html">面试总结20203回答版</a></p><p>面试建议投递时间：9：00 - 10：00 以及下午 3：00 - 5：00</p><hr><h4 id="面试题回答" tabindex="-1">面试题回答 <a class="header-anchor" href="#面试题回答" aria-label="Permalink to &quot;面试题回答&quot;">​</a></h4><p>看【面试煎熬成蛋_面试速刷版_第二版】</p>',9)])])}const _=i(u,[["render",r]]);export{h as __pageData,_ as default};
